def compose(left, connector, right):
    relation = {
      "COPULATIVE":"AND",
      "DISJUNCTIVE":"OR",
      "CONJUNCTIVE_SEQUENCE":"SEQUENCE",
      "CAUSATIVE":"CAUSE",
      "INFERENTIAL":"INFER",
      "DUBITATIVE":"QUESTION"
    }[connector]
    return (relation, left, right)

cases = {
  "copulative": compose("A", "COPULATIVE", "B"),
  "disjunctive": compose("A", "DISJUNCTIVE", "B"),
  "causative": compose("A", "CAUSATIVE", "B"),
  "sequence": compose("A", "CONJUNCTIVE_SEQUENCE", "B")
}
result = cases
